module min_replant (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] n,\n    input [7:0] species [0:15],\n    output reg [7:0] result,\n    output reg done\n);\n\n    parameter MAX_N = 16;\n\n    // State declarations\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] INIT = 3'd1;\n    localparam [2:0] OUTER_LOOP = 3'd2;\n    localparam [2:0] INNER_LOOP = 3'd3;\n    localparam [2:0] UPDATE_DP = 3'd4;\n    localparam [2:0] CALC_RESULT = 3'd5;\n    localparam [2:0] DONE_STATE = 3'd6;\n\n    // State registers\n    reg [2:0] state, next_state;\n\n    // DP array and related registers\n    reg [7:0] dp [0:15];\n    reg [7:0] max_dp;\n    reg [7:0] current_dp;\n\n    // Loop counters\n    reg [7:0] i;\n    reg [7:0] j;\n\n    // Cycle counter to prevent infinite loops\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd200;\n\n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            next_state <= IDLE;\n            result <= 8'd0;\n            done <= 1'b0;\n            max_dp <= 8'd0;\n            current_dp <= 8'd0;\n            i <= 8'd0;\n            j <= 8'd0;\n            cycle_count <= 8'd0;\n            // Initialize dp array\n            integer k;\n            for (k = 0; k < MAX_N; k = k + 1) begin\n                dp[k] <= 8'd0;\n            end\n        end else begin\n            state <= next_state;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_count <= 8'd0;\n                    if (start) begin\n                        next_state <= INIT;\n                    end else begin\n                        next_state <= IDLE;\n                    end\n                end\n\n                INIT: begin\n                    // Initialize for i=0\n                    dp[0] <= 8'd1;\n                    max_dp <= 8'd1;\n                    i <= 8'd0;\n                    j <= 8'd0;\n                    next_state <= OUTER_LOOP;\n                end\n\n                OUTER_LOOP: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    if (i < n - 8'd1) begin\n                        i <= i + 8'd1;\n                        current_dp <= 8'd1;\n                        j <= 8'd0;\n                        next_state <= INNER_LOOP;\n                    end else begin\n                        next_state <= CALC_RESULT;\n                    end\n                end\n\n                INNER_LOOP: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    if (j < i) begin\n                        if (species[j] <= species[i] && dp[j] + 8'd1 > current_dp) begin\n                            current_dp <= dp[j] + 8'd1;\n                        end\n                        j <= j + 8'd1;\n                        next_state <= INNER_LOOP;\n                    end else begin\n                        next_state <= UPDATE_DP;\n                    end\n                end\n\n                UPDATE_DP: begin\n                    dp[i] <= current_dp;\n                    if (current_dp > max_dp) begin\n                        max_dp <= current_dp;\n                    end\n                    next_state <= OUTER_LOOP;\n                end\n\n                CALC_RESULT: begin\n                    result <= n - max_dp;\n                    next_state <= DONE_STATE;\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n\n                default: begin\n                    next_state <= IDLE;\n                    done <= 1'b0;\n                end\n            endcase\n        end\n    end\n\nendmodule